SELECT id, event_code, event_name, event_grade_dict, event_time, event_type_large_category, event_type_middle_category, event_type_small_category, province_code, city_code, country_code, specific_location, longitude, latitude, event_describe, remark, tenant_id, industry_code, app_ver_code, create_time, creator, update_time, modifier, delete_flag, status FROM vm_emergency_event_info a WHERE a.delete_flag = 0 AND a.industry_code = #{industryCode} AND a.tenant_id = #{tenantId,jdbcType=VARCHAR}
AND a.event_code LIKE CONCAT('%', #{eventCode}, '%')
AND a.event_name LIKE CONCAT('%', #{eventName}, '%')
AND a.event_time >= #{eventTimeStart}
AND a.event_time <= #{eventTimeEnd}
AND (a.event_name LIKE CONCAT('%', #{keyWord}, '%') OR a.event_code LIKE CONCAT('%', #{keyWord}, '%'))
AND ( a.event_type_large_category in
#{item, jdbcType=INTEGER}
OR a.event_type_middle_category in
#{item, jdbcType=INTEGER}
OR a.event_type_small_category in
#{item, jdbcType=INTEGER}
)
AND ( a.event_type_middle_category in
#{item, jdbcType=INTEGER}
OR a.event_type_small_category in
#{item, jdbcType=INTEGER}
)
AND a.event_type_small_category in
#{item, jdbcType=INTEGER}
AND a.event_grade_dict in
#{item}
AND a.status in
#{item}
ORDER BY a.event_time DESC
ORDER BY a.event_time ASC
